• Website activity events
• Custom integrations

Expected payload:
{
  "event_type": "new_lead" | "engagement" | "form_submit" | "page_visit",
  "lead": { leadId, email, first_name, ... },
  "activity": { type, timestamp, details }
}

parameters.jsCode:
// Normalize lead data from different sources
const input = $input.first().json;
const config = $('Set Config').first().json;

// Determine source and extract lead data
let lead = {};
let eventType = 'manual';
let activity = {};
let source = 'unknown';

// From webhook
if (input.body) {
  const body = input.body;
  lead = body.lead || body;
  eventType = body.event_type || 'new_lead';
  activity = body.activity || {};
  source = 'webhook';
}
// From HubSpot trigger
else if (input.properties) {
  lead = {
    leadId: input.id || input.vid,
    email: input.properties.email?.value || input.properties.email,
    first_name: input.properties.firstname?.value || input.properties.firstname,
    last_name: input.properties.lastname?.value || input.properties.lastname,
    company: input.properties.company?.value || input.properties.company,
    role: input.properties.jobtitle?.value || input.properties.jobtitle,
    phone: input.properties.phone?.value || input.properties.phone,
    owner: input.properties.hubspot_owner_id?.value,
    status: input.properties.lifecyclestage?.value || 'lead',
    opt_out: input.properties.hs_email_optout?.value === 'true',
    consent_sms: input.properties.consent_sms?.value === 'true',
    lead_source: input.properties.hs_lead_source?.value || input.properties.hs_analytics_source?.value,
    last_activity_type: input.properties.hs_last_sales_activity_type?.value,
    last_activity_ts: input.properties.hs_last_sales_activity_timestamp?.value,
    last_touch_ts: input.properties.notes_last_contacted?.value
  };
  eventType = 'new_lead';
  source = 'hubspot';
}
// From Airtable
else if (input.fields) {
  lead = {
    leadId: input.id,
    email: input.fields.Email || input.fields.email,
    first_name: input.fields.FirstName || input.fields.first_name,
    last_name: input.fields.LastName || input.fields.last_name,
    company: input.fields.Company || input.fields.company,
    role: input.fields.Role || input.fields.role,
    phone: input.fields.Phone || input.fields.phone,
    owner: input.fields.Owner || input.fields.owner,
    status: input.fields.Status || input.fields.status || 'lead',
    opt_out: input.fields.OptOut || input.fields.opt_out || false,
    consent_sms: input.fields.ConsentSMS || input.fields.consent_sms || false,
    lead_source: input.fields.LeadSource || input.fields.lead_source,
    last_activity_type: input.fields.LastActivityType || input.fields.last_activity_type,
    last_activity_ts: input.fields.LastActivityTimestamp || input.fields.last_activity_ts,
    last_touch_ts: input.fields.LastTouchTimestamp || input.fields.last_touch_ts
  };
  eventType = input.fields.event_type || 'new_lead';
  source = 'airtable';
}
// From Google Calendar (meeting booked)
else if (input.summary || input.attendees) {
  const attendeeEmail = input.attendees?.find(a => !a.self)?.email;
  lead = {
    leadId: attendeeEmail,
    email: attendeeEmail
  };
  eventType = 'meeting_booked';
  activity = {
    type: 'meeting_booked',
    timestamp: input.start?.dateTime || new Date().toISOString(),
    details: input.summary
  };
  source = 'calendar';
}
// From manual trigger or test
else if (input.leadId || input.email) {
  lead = input;
  eventType = input.event_type || 'manual';
  source = 'manual';
}

// Generate unique lead ID if missing
if (!lead.leadId && lead.email) {
  lead.leadId = lead.email.toLowerCase().replace(/[^a-z0-9]/g, '_');
}

// Normalize timestamps
const now = new Date().toISOString();
lead.last_activity_ts = lead.last_activity_ts || now;
lead.last_touch_ts = lead.last_touch_ts || null;

// Determine sequence based on event type
let sequenceName = 'new_lead';
let triggerType = eventType;

switch (eventType) {
  case 'new_lead':
  case 'form_submit':
    sequenceName = 'new_lead';
    break;
  case 'engagement':
  case 'email_open':
  case 'email_click':
  case 'page_visit':
    sequenceName = 'engaged_lead';
    break;
  case 'inactivity':
    sequenceName = 'nudge';
    break;
  case 'meeting_booked':
    sequenceName = 'post_meeting';
    break;
  default:
    sequenceName = 'new_lead';
}

return {
  lead,
  eventType,
  triggerType,
  sequenceName,
  activity,
  source,
  processedAt: now,
  config: {
    testMode: config.testMode,
    useSms: config.useSms,
    requireSmsConsent: config.requireSmsConsent,
    ownerNotificationEmail: config.ownerNotificationEmail
  }
};

// Check stop conditions
const input = $input.first().json;
const lead = input.lead;
const config = $('Set Config').first().json;

const stopReasons = [];
let shouldStop = false;

// 1. Check opt-out
if (lead.opt_out === true || lead.opt_out === 'true') {
  stopReasons.push('Lead has opted out');
  shouldStop = true;
}

// 2. Check disqualifying statuses
const disqualifyingStatuses = ['customer', 'closed_lost', 'disqualified', 'closed lost', 'won', 'lost'];
const leadStatus = (lead.status || '').toLowerCase();
if (disqualifyingStatuses.some(s => leadStatus.includes(s))) {
  stopReasons.push(`Lead status is ${lead.status}`);
  shouldStop = true;
}

// 3. Check if lead replied recently (would need reply tracking)
if (lead.replied_recently === true) {
  stopReasons.push('Lead replied recently');
  shouldStop = true;
}

// 4. Check if meeting already booked (unless this IS the meeting trigger)
if (lead.meeting_booked === true && input.eventType !== 'meeting_booked') {
  stopReasons.push('Meeting already booked');
  shouldStop = true;
}

// 5. Check for missing critical data
const missingFields = [];
if (!lead.email) missingFields.push('email');
if (!lead.leadId) missingFields.push('leadId');

if (missingFields.length > 0) {
  stopReasons.push(`Missing critical fields: ${missingFields.join(', ')}`);
  shouldStop = true;
}

return {
  ...input,
  stopCheck: {
    shouldStop,
    stopReasons,
    missingFields,
    checkedAt: new Date().toISOString()
  }
};

// Check quiet hours
const input = $input.first().json;
const config = $('Set Config').first().json;

const timezone = config.timezone || 'America/New_York';
const quietStart = config.quietHoursStart || '20:00';
const quietEnd = config.quietHoursEnd || '08:00';

// Get current time in configured timezone
const now = new Date();
const options = { timeZone: timezone, hour: '2-digit', minute: '2-digit', hour12: false };
const timeStr = now.toLocaleTimeString('en-US', options);
const [currentHour, currentMinute] = timeStr.split(':').map(Number);
const currentMinutes = currentHour * 60 + currentMinute;

// Parse quiet hours
const [startHour, startMinute] = quietStart.split(':').map(Number);
const [endHour, endMinute] = quietEnd.split(':').map(Number);
const startMinutes = startHour * 60 + startMinute;
const endMinutes = endHour * 60 + endMinute;

// Check if current time is in quiet hours
let inQuietHours = false;
if (startMinutes > endMinutes) {
  // Quiet hours span midnight (e.g., 20:00 to 08:00)
  inQuietHours = currentMinutes >= startMinutes || currentMinutes < endMinutes;
} else {
  // Quiet hours within same day
  inQuietHours = currentMinutes >= startMinutes && currentMinutes < endMinutes;
}

// Calculate minutes until quiet hours end
let minutesUntilSendAllowed = 0;
if (inQuietHours) {
  if (currentMinutes >= startMinutes) {
    // After midnight scenario
    minutesUntilSendAllowed = (24 * 60 - currentMinutes) + endMinutes;
  } else {
    minutesUntilSendAllowed = endMinutes - currentMinutes;
  }
}

return {
  ...input,
  quietHoursCheck: {
    inQuietHours,
    currentTime: timeStr,
    timezone,
    quietStart,
    quietEnd,
    minutesUntilSendAllowed,
    checkedAt: now.toISOString()
  }
};

// Dedupe and idempotency check
// Uses Google Sheets as the source of truth for sent messages
const input = $input.first().json;
const lead = input.lead;
const sequenceName = input.sequenceName;

// Get step from sequence definition
const sequences = JSON.parse($('Set Sequences & Value Props').first().json.sequences);
const sequence = sequences[sequenceName];

if (!sequence) {
  return {
    ...input,
    dedupeCheck: {
      isDuplicate: true,
      reason: `Unknown sequence: ${sequenceName}`,
      dedupeKey: null
    }
  };
}

// Determine current step (default to step 1 for new sequences)
const currentStep = input.currentStep || 1;
const stepConfig = sequence.steps.find(s => s.step === currentStep);

if (!stepConfig) {
  return {
    ...input,
    dedupeCheck: {
      isDuplicate: true,
      reason: `Invalid step ${currentStep} for sequence ${sequenceName}`,
      dedupeKey: null
    }
  };
}

// Generate dedupe key: leadId + sequenceName + stepNumber
const dedupeKey = `${lead.leadId}_${sequenceName}_${currentStep}`;

// Note: Actual dedupe lookup happens in the next node via Sheets
// This node prepares the key and step configuration

return {
  ...input,
  currentStep,
  stepConfig,
  sequence: {
    name: sequence.name,
    key: sequenceName,
    totalSteps: sequence.steps.length
  },
  dedupeKey,
  dedupeCheck: {
    isDuplicate: false, // Will be updated by Sheets lookup
    dedupeKey,
    preparedAt: new Date().toISOString()
  }
};

// Process dedupe lookup result
const input = $input.first().json;
const items = $input.all();

// Check if any rows were returned from the lookup
const existingEntry = items.length > 0 && items[0].json.dedupe_key;

let result;

if (existingEntry) {
  // Entry exists - this is a duplicate
  result = {
    ...input,
    dedupeCheck: {
      ...input.dedupeCheck,
      isDuplicate: true,
      reason: 'Step already sent for this lead',
      existingEntry: items[0].json
    }
  };
} else {
  // No entry - not a duplicate
  result = {
    ...input,
    dedupeCheck: {
      ...input.dedupeCheck,
      isDuplicate: false,
      reason: null
    }
  };
}

return result;

// Rate limit check
const input = $input.first().json;
const lead = input.lead;
const config = $('Set Config').first().json;

const maxTouchesPerDay = config.maxTouchesPerDayPerLead || 2;
const minHoursBetween = config.minHoursBetweenTouches || 16;

// Check last touch timestamp
const lastTouchTs = lead.last_touch_ts;
let hoursSinceLastTouch = Infinity;

if (lastTouchTs) {
  const lastTouch = new Date(lastTouchTs);
  const now = new Date();
  hoursSinceLastTouch = (now - lastTouch) / (1000 * 60 * 60);
}

const belowMinInterval = hoursSinceLastTouch < minHoursBetween;

// Note: Daily touch count would need to be tracked separately
// For now, we use the last touch timestamp as the primary rate limit

return {
  ...input,
  rateLimitCheck: {
    exceedsLimit: belowMinInterval,
    hoursSinceLastTouch: Math.round(hoursSinceLastTouch * 10) / 10,
    minHoursBetween,
    maxTouchesPerDay,
    reason: belowMinInterval ? `Only ${hoursSinceLastTouch.toFixed(1)} hours since last touch (min: ${minHoursBetween})` : null,
    checkedAt: new Date().toISOString()
  }
};

// Prepare context for LLM message generation
const input = $input.first().json;
const lead = input.lead;
const stepConfig = input.stepConfig;
const sequence = input.sequence;
const config = $('Set Config').first().json;
const valueProps = JSON.parse($('Set Sequences & Value Props').first().json.valueProps);

// Format last activity for context
let lastActivityContext = 'No recent activity recorded';
if (lead.last_activity_type && lead.last_activity_ts) {
  const activityDate = new Date(lead.last_activity_ts);
  const daysAgo = Math.round((new Date() - activityDate) / (1000 * 60 * 60 * 24));
  lastActivityContext = `${lead.last_activity_type} ${daysAgo} day(s) ago`;
}

// Build lead context
const leadContext = {
  first_name: lead.first_name || null,
  last_name: lead.last_name || null,
  company: lead.company || null,
  role: lead.role || null,
  email: lead.email,
  lead_source: lead.lead_source || 'Unknown',
  last_activity: lastActivityContext,
  consent_sms: lead.consent_sms === true,
  has_phone: !!lead.phone
};

// Determine available data quality
const availableFields = Object.entries(leadContext)
  .filter(([k, v]) => v !== null && v !== 'Unknown' && v !== false)
  .map(([k]) => k);

const missingCriticalFields = [];
if (!leadContext.first_name) missingCriticalFields.push('first_name');
if (!leadContext.company) missingCriticalFields.push('company');

return {
  ...input,
  llmContext: {
    lead: leadContext,
    sequence: {
      name: sequence.name,
      step: stepConfig.step,
      totalSteps: sequence.totalSteps,
      template: stepConfig.template,
      channel: stepConfig.channel
    },
    valueProps: valueProps,
    availableFields,
    missingCriticalFields,
    useSms: config.useSms && stepConfig.channel === 'sms_or_email' && leadContext.consent_sms && leadContext.has_phone
  }
};

