parameters.jsCode:
// Parse and validate LLM response
const input = $input.first().json;
const llmResponse = input.message?.content || input.text || input.content;
const config = $('Set Config').first().json;

let parsedMessage;
try {
  // Clean up response (remove markdown code blocks if present)
  let cleanResponse = llmResponse;
  if (cleanResponse.includes('```')) {
    cleanResponse = cleanResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  }
  parsedMessage = JSON.parse(cleanResponse.trim());
} catch (e) {
  // Fallback if parsing fails
  parsedMessage = {
    subject: 'Following up',
    body: 'I wanted to follow up on my previous message. Would you have time for a quick call this week?',
    sms: 'Hi! Following up - do you have time for a quick call?',
    confidence: 0.5,
    personalization_used: [],
    value_prop_selected: null,
    compliance_ok: true,
    stop_recommended: false,
    notes: 'Fallback message due to LLM parsing error: ' + e.message
  };
}

// Get the previous context
const prevNode = $('Prepare LLM Context').first().json;

// Validate required fields
const requiredFields = ['subject', 'body', 'confidence', 'compliance_ok'];
const missingFields = requiredFields.filter(f => parsedMessage[f] === undefined);

if (missingFields.length > 0) {
  parsedMessage.notes = (parsedMessage.notes || '') + ` Missing fields: ${missingFields.join(', ')}`;
  parsedMessage.confidence = Math.min(parsedMessage.confidence || 0.5, 0.5);
}

// Determine if confidence meets threshold
const confidenceThreshold = config.confidenceThreshold || 0.7;
const meetsConfidenceThreshold = parsedMessage.confidence >= confidenceThreshold;

return {
  ...prevNode,
  generatedMessage: parsedMessage,
  messageValidation: {
    meetsConfidenceThreshold,
    confidenceThreshold,
    actualConfidence: parsedMessage.confidence,
    complianceOk: parsedMessage.compliance_ok,
    stopRecommended: parsedMessage.stop_recommended,
    validatedAt: new Date().toISOString()
  }
};

