// Prepare log entry
const input = $input.first().json;
const config = $('Set Config').first().json;
const lead = input.lead || {};
const sequence = input.sequence || {};

// Determine action taken and channel
let actionTaken = input.actionTaken || 'sent';
let channel = input.channel || (input.llmContext?.useSms ? 'sms' : 'email');
let error = input.error || null;

// Handle different entry points to this node
if (input.stopCheck?.shouldStop) {
  actionTaken = 'blocked';
  error = input.stopCheck.stopReasons.join('; ');
}

if (input.dedupeCheck?.isDuplicate) {
  actionTaken = 'skipped_duplicate';
  error = input.dedupeCheck.reason;
}

if (input.rateLimitCheck?.exceedsLimit) {
  actionTaken = 'skipped_rate_limit';
  error = input.rateLimitCheck.reason;
}

if (input.messageValidation?.complianceOk === false || input.generatedMessage?.compliance_ok === false) {
  actionTaken = 'blocked_compliance';
  error = 'Compliance check failed';
}

if (input.generatedMessage?.stop_recommended) {
  actionTaken = 'blocked_stop_recommended';
  error = 'LLM recommended stopping';
}

// Build message preview (first 100 chars)
let messagePreview = '';
if (input.generatedMessage) {
  const msg = channel === 'sms' ? input.generatedMessage.sms : input.generatedMessage.body;
  messagePreview = (msg || '').substring(0, 100);
}

const logEntry = {
  timestamp: new Date().toISOString(),
  leadId: lead.leadId || '',
  email: lead.email || '',
  sequence: sequence.name || input.sequenceName || '',
  step: input.currentStep || 1,
  channel: channel,
  subject: input.generatedMessage?.subject || '',
  message_preview: messagePreview,
  trigger_type: input.triggerType || input.eventType || '',
  last_activity_type: lead.last_activity_type || '',
  confidence: input.generatedMessage?.confidence || 0,
  compliance_ok: input.generatedMessage?.compliance_ok ?? true,
  action_taken: actionTaken,
  error: error || '',
  dedupe_key: input.dedupeKey || '',
  test_mode: config.testMode ? 'TRUE' : 'FALSE',
  value_prop_used: input.generatedMessage?.value_prop_selected || '',
  personalization_fields: (input.generatedMessage?.personalization_used || []).join(', ')
};

return logEntry;

