// Handle inactivity check trigger
const config = $('Set Config').first().json;
const inactivityDays = config.inactivityThresholdDays || 3;

// This would typically query the CRM for inactive leads
// For now, we output the trigger info for the next nodes to use
return {
  event_type: 'inactivity',
  triggerType: 'inactivity_check',
  inactivity_threshold_days: inactivityDays,
  triggered_at: new Date().toISOString(),
  note: 'Connect this to your CRM query to fetch leads inactive for ' + inactivityDays + ' days'
};

// Process calendar trigger for meeting booked
const input = $input.first().json;

// Extract attendee email from calendar event
let attendeeEmail = null;
if (input.attendees && Array.isArray(input.attendees)) {
  // Find first non-organizer attendee
  const attendee = input.attendees.find(a => !a.organizer && !a.self);
  attendeeEmail = attendee?.email;
}

return {
  event_type: 'meeting_booked',
  triggerType: 'meeting_booked',
  meeting: {
    summary: input.summary,
    start: input.start,
    end: input.end,
    attendeeEmail: attendeeEmail,
    calendarEventId: input.id
  },
  lead: {
    email: attendeeEmail,
    leadId: attendeeEmail?.toLowerCase().replace(/[^a-z0-9]/g, '_')
  },
  triggered_at: new Date().toISOString()
};

// Handle meeting booked - stop sequences and send confirmation
const input = $input.first().json;

// Override sequence to post_meeting
return {
  ...input,
  sequenceName: 'post_meeting',
  currentStep: 1,
  eventType: 'meeting_booked',
  shouldStopOtherSequences: true,
  note: 'Meeting booked - stopping other sequences and sending confirmation'
};

// Merge paths for sending channels
const input = $input.first().json;

// Get the send result from the previous node
const sendResult = {
  success: true,
  channel: input.llmContext?.useSms ? 'sms' : 'email',
  sentAt: new Date().toISOString()
};

return {
  ...input,
  sendResult,
  actionTaken: 'sent',
  channel: sendResult.channel
};

// Log stop/skip reasons
const input = $input.first().json;

let reason = 'unknown';
let actionTaken = 'skipped';

if (input.stopCheck?.shouldStop) {
  reason = input.stopCheck.stopReasons.join('; ');
  actionTaken = 'blocked_stop_condition';
}

if (input.dedupeCheck?.isDuplicate) {
  reason = input.dedupeCheck.reason;
  actionTaken = 'skipped_duplicate';
}

if (input.rateLimitCheck?.exceedsLimit) {
  reason = input.rateLimitCheck.reason;
  actionTaken = 'skipped_rate_limit';
}

return {
  ...input,
  actionTaken,
  error: reason,
  channel: 'none'
};

// Schedule next step in sequence
const input = $input.first().json;
const sequences = JSON.parse($('Set Sequences & Value Props').first().json.sequences);
const sequence = sequences[input.sequenceName];
const currentStep = input.currentStep || 1;

// Check if there's a next step
const nextStep = currentStep + 1;
const nextStepConfig = sequence?.steps.find(s => s.step === nextStep);

if (!nextStepConfig) {
  // No more steps - sequence complete
  return {
    ...input,
    sequenceComplete: true,
    nextStep: null
  };
}

// Calculate delay for next step
const delayMs = (nextStepConfig.delayDays * 24 * 60 * 60 * 1000) + 
                (nextStepConfig.delayHours * 60 * 60 * 1000);

return {
  ...input,
  sequenceComplete: false,
  nextStep: {
    step: nextStep,
    config: nextStepConfig,
    delayMs,
    scheduledFor: new Date(Date.now() + delayMs).toISOString()
  }
};

// Prepare for next step execution
const input = $input.first().json;

return {
  ...input,
  currentStep: input.nextStep.step,
  stepConfig: input.nextStep.config,
  previousStep: input.currentStep,
  resumedAt: new Date().toISOString()
};
